#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int start;
    int end;
    int price;
} Application;

int compare(const void *a, const void *b) {
    Application *app1 = (Application *)a;
    Application *app2 = (Application *)b;
    if (app1->end != app2->end)
        return app1->end - app2->end;
    return app1->start - app2->start;
}

int max(int a, int b) {
    return (a > b) ? a : b;
}

int main() {
    int n;
    while (scanf("%d", &n) == 1) {
        if (n == 0) break;

        Application *apps = (Application *)malloc(n * sizeof(Application));
        for (int i = 0; i < n; i++) {
            scanf("%d %d %d", &apps[i].start, &apps[i].end, &apps[i].price);
        }

        // Sort by end day ascending
        qsort(apps, n, sizeof(Application), compare);

        // dp[i] = max income using first i applications (0-indexed)
        int *dp = (int *)malloc((n + 1) * sizeof(int));
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            // Option 1: skip this application
            dp[i] = dp[i - 1];

            // Option 2: take this application
            // Find last non-overlapping application
            int lo = 0, hi = i - 2, best = -1;
            while (lo <= hi) {
                int mid = (lo + hi) / 2;
                if (apps[mid].end < apps[i - 1].start) {
                    best = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            int prev = (best == -1) ? 0 : dp[best + 1];
            dp[i] = max(dp[i], prev + apps[i - 1].price);
        }

        printf("%d\n", dp[n]);

        free(apps);
        free(dp);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int s, e, w;
} Interval;

typedef struct {
    int x, type, id;
} Event;

/*
type:
0 = end event
1 = start event
For same coordinate, end events are processed before start events.
*/

static int cmp_interval_end(const void *a, const void *b) {
    const Interval *A = (const Interval *)a;
    const Interval *B = (const Interval *)b;
    if (A->e != B->e) return A->e - B->e;
    if (A->s != B->s) return A->s - B->s;
    return A->w - B->w;
}

static int cmp_event(const void *a, const void *b) {
    const Event *A = (const Event *)a;
    const Event *B = (const Event *)b;
    if (A->x != B->x) return A->x - B->x;
    if (A->type != B->type) return A->type - B->type; /* end before start */
    return A->id - B->id;
}

static ll maxll(ll a, ll b) { return a > b ? a : b; }

int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n) {
        Interval *it = (Interval *)malloc((n + 1) * sizeof(Interval));
        Event *ev = (Event *)malloc((2 * n) * sizeof(Event));
        int *ends = (int *)malloc((n + 1) * sizeof(int));

        for (int i = 1; i <= n; ++i) {
            scanf("%d %d %d", &it[i].s, &it[i].e, &it[i].w);
        }

        /* Sort intervals by end time to build predecessor p[i] */
        Interval *sorted = (Interval *)malloc(n * sizeof(Interval));
        for (int i = 0; i < n; ++i) sorted[i] = it[i + 1];
        qsort(sorted, n, sizeof(Interval), cmp_interval_end);

        /* Reindex intervals in sorted-by-end order */
        for (int i = 1; i <= n; ++i) {
            it[i] = sorted[i - 1];
            ends[i] = it[i].e;
        }
        free(sorted);

        /* p[i]: largest index j < i with end[j] < start[i] */
        int *p = (int *)malloc((n + 1) * sizeof(int));
        ends[0] = -2147483647;
        for (int i = 1; i <= n; ++i) {
            int lo = 0, hi = i - 1, ans = 0;
            while (lo <= hi) {
                int mid = (lo + hi) >> 1;
                if (ends[mid] < it[i].s) {
                    ans = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            p[i] = ans;
        }

        /*
        DP with sweep line over coordinates.

        Let best0[t] = best value using intervals fully ended up to current point, with 0 active interval.
        Let best1[k] = best value where interval k is currently active and occupies one room,
                       plus any finished intervals before its start.
        Let active pair (a,b) value = base before both + w[a]+w[b], but we avoid explicit O(n^2).

        We maintain:
        - dp0[i]: best value using intervals among first i (by end time) with capacity 2 and no active interval
                  this is what we ultimately need at ends.
        - one_active[i]: best value of schedule where interval i is active now, alone.
          value = dp0[p[i]] + w[i]
        - two_active involving current starting interval i with some earlier active j:
          value = one_active[j based on state valid before s_i] + w[i]

        To support this efficiently, sweep events:
        - when interval j starts, it can become active with value dpEnded[p_j] + w_j
        - also it can pair with any currently active interval k, giving two rooms occupied
        - when interval j ends, we update dpEnded at index j from:
            * not taking j
            * taking j alone after compatible finished intervals
            * taking j together with another overlapping interval tracked when both active
        */

        /* Build events on sorted-by-end indices */
        for (int i = 1; i <= n; ++i) {
            ev[2 * (i - 1)] = (Event){it[i].e, 0, i};
            ev[2 * (i - 1) + 1] = (Event){it[i].s, 1, i};
        }
        qsort(ev, 2 * n, sizeof(Event), cmp_event);

        ll *dp = (ll *)malloc((n + 1) * sizeof(ll));
        ll *singleVal = (ll *)malloc((n + 1) * sizeof(ll));
        ll *pairEndVal = (ll *)malloc((n + 1) * sizeof(ll));

        for (int i = 0; i <= n; ++i) {
            dp[i] = 0;
            singleVal[i] = 0;
            pairEndVal[i] = 0;
        }

        /*
        We need max single active value among currently active intervals.
        Also for starting interval i, pairing with active j gives value singleVal[j] + w[i].
        This is valid because singleVal[j] already includes best finished schedule before start[j],
        and since j is active now, start[j] <= current point < end[j]. Adding i is valid iff overlap
        in time only uses second room, which is always okay because only two rooms total.
        */
        ll activeSingleMax = -(1LL << 60);

        /* To support removals from active set, use multiset via heap with lazy deletion */
        ll *heapAdd = (ll *)malloc((n + 5) * sizeof(ll));
        ll *heapDel = (ll *)malloc((n + 5) * sizeof(ll));
        int szAdd = 0, szDel = 0;

        #define HEAP_PUSH(heap, sz, val) do { \
            int _i = ++(sz); \
            (heap)[_i] = (val); \
            while (_i > 1) { \
                int _p = _i >> 1; \
                if ((heap)[_p] >= (heap)[_i]) break; \
                ll _tmp = (heap)[_p]; (heap)[_p] = (heap)[_i]; (heap)[_i] = _tmp; \
                _i = _p; \
            } \
        } while (0)

        #define HEAP_POP(heap, sz) do { \
            (heap)[1] = (heap)[(sz)--]; \
            int _i = 1; \
            while (1) { \
                int _l = _i << 1, _r = _l + 1, _m = _i; \
                if (_l <= (sz) && (heap)[_l] > (heap)[_m]) _m = _l; \
                if (_r <= (sz) && (heap)[_r] > (heap)[_m]) _m = _r; \
                if (_m == _i) break; \
                ll _tmp = (heap)[_i]; (heap)[_i] = (heap)[_m]; (heap)[_m] = _tmp; \
                _i = _m; \
            } \
        } while (0)

        auto void heap_clean(void) {
            while (szAdd > 0 && szDel > 0 && heapAdd[1] == heapDel[1]) {
                HEAP_POP(heapAdd, szAdd);
                HEAP_POP(heapDel, szDel);
            }
        }

        int endedPtr = 0; /* dp[endedPtr] is best among intervals with end processed so far */

        for (int ei = 0; ei < 2 * n; ++ei) {
            int id = ev[ei].id;

            if (ev[ei].type == 0) {
                /* interval id ends */
                /* incorporate this interval into dp prefix */
                dp[id] = dp[id - 1];
                dp[id] = maxll(dp[id], dp[p[id]] + (ll)it[id].w);
                dp[id] = maxll(dp[id], pairEndVal[id]);
                endedPtr = id;

                /* remove its single-active contribution from active set */
                HEAP_PUSH(heapDel, szDel, singleVal[id]);
                heap_clean();
                activeSingleMax = (szAdd > 0 ? heapAdd[1] : -(1LL << 60));
            } else {
                /* interval id starts */
                /* dp[p[id]] is already final since p[id] intervals end before start[id] */
                singleVal[id] = dp[p[id]] + (ll)it[id].w;

                /* if paired with any currently active interval */
                if (szAdd > 0) {
                    heap_clean();
                    if (szAdd > 0) {
                        ll cand = heapAdd[1] + (ll)it[id].w;
                        if (cand > pairEndVal[id]) pairEndVal[id] = cand;
                    }
                }

                /* also alone can end later and be handled by dp[p]+w at its end */

                /* activate */
                HEAP_PUSH(heapAdd, szAdd, singleVal[id]);
                heap_clean();
                activeSingleMax = heapAdd[1];
            }
        }

        printf("%lld\n", dp[n]);

        free(it);
        free(ev);
        free(ends);
        free(p);
        free(dp);
        free(singleVal);
        free(pairEndVal);
        free(heapAdd);
        free(heapDel);
    }
    return 0;
}

