int cmp(const void *a, const void *b) {
    int *x = (int*)a, *y = (int*)b;
    return x[1] - y[1];
}

int main() {
    int n;
    while (scanf("%d", &n) == 1 && n != 0) {
        int app[205][3]; // start, end, weight
        for (int i = 1; i <= n; i++)
            scanf("%d %d %d", &app[i][0], &app[i][1], &app[i][2]);
        // sort by end time, index 1..n
        qsort(app+1, n, sizeof(app[0]), cmp);

        // dp[i][j] = max revenue, i>=j, last used intervals
        static int dp[205][205];
        memset(dp, -1, sizeof(dp));
        dp[0][0] = 0;
        int ans = 0;

        for (int i = 0; i <= n; i++)
            for (int j = 0; j <= i; j++) {
                if (dp[i][j] < 0) continue;
                if (dp[i][j] > ans) ans = dp[i][j];
                // try adding interval k
                for (int k = 1; k <= n; k++) {
                    // k must not conflict with i and be after i or j
                    int si = (i==0)?0:app[i][1], sj = (j==0)?0:app[j][1];
                    if (app[k][0] > si) { // assign to room1 (last=i)
                        int ni = k, nj = j;
                        if (ni < nj) { int t=ni; ni=nj; nj=t; }
                        if (dp[ni][nj] < dp[i][j]+app[k][2])
                            dp[ni][nj] = dp[i][j]+app[k][2];
                    }
                    if (app[k][0] > sj && k != i) { // assign to room2
                        int ni = i, nj = k;
                        if (ni < nj) { int t=ni; ni=nj; nj=t; }
                        if (dp[ni][nj] < dp[i][j]+app[k][2])
                            dp[ni][nj] = dp[i][j]+app[k][2];
                    }
                }
            }
        printf("%d\n", ans);
    }
}

