        int n;
        cin >> n;
        if (n == 0) break;

        vector<Application> apps(n);
        vector<int> days;
        for (int i = 0; i < n; ++i) {
            cin >> apps[i].start >> apps[i].end >> apps[i].price;
            days.push_back(apps[i].start);
            days.push_back(apps[i].end);
        }

        // Coordinate compression
        sort(days.begin(), days.end());
        days.erase(unique(days.begin(), days.end()), days.end());
        int m = days.size();

        // Map start and end to compressed indices
        for (auto &app : apps) {
            app.start = lower_bound(days.begin(), days.end(), app.start) - days.begin();
            app.end = lower_bound(days.begin(), days.end(), app.end) - days.begin();
        }

        // Group applications by end day
        vector<vector<pair<int, int>>> byEnd(m);
        for (auto &app : apps) {
            byEnd[app.end].push_back({app.start, app.price});
        }

        // DP: dp[i] = max income considering days up to compressed index i
        vector<long long> dp(m + 1, 0);
        for (int i = 0; i < m; ++i) {
            // Option: skip day i (take previous value)
            dp[i + 1] = dp[i];
            // Option: take an application ending at day i
            for (auto &p : byEnd[i]) {
                int start = p.first;
                long long price = p.second;
                dp[i + 1] = max(dp[i + 1], dp[start] + price);
            }
        }

        cout << dp[m] << "\n";
    }

    return 0;
}

