        vector<int> idx(n);
        iota(idx.begin(),idx.end(),1);
        sort(idx.begin(),idx.end(),[&](int a,int b){return e[a]<e[b];});
        vector<int> S(n+1),E(n+1),W(n+1);
        for(int i=1;i<=n;i++){S[i]=s[idx[i-1]];E[i]=e[idx[i-1]];W[i]=w[idx[i-1]];}

        vector<vector<long long>> dp(n+1, vector<long long>(n+1,-1));
        dp[0][0]=0;
        long long ans=0;
        for(int i=0;i<=n;i++) for(int j=0;j<=i;j++){
            if(dp[i][j]<0) continue;
            ans=max(ans,dp[i][j]);
            for(int k=i+1;k<=n;k++){
                if(S[k]>E[i]){
                    int a=k,b=j; if(a<b)swap(a,b);
                    dp[a][b]=max(dp[a][b],dp[i][j]+W[k]);
                }
                if(S[k]>E[j]){
                    int a=k,b=i; if(a<b)swap(a,b);
                    dp[a][b]=max(dp[a][b],dp[i][j]+W[k]);
                }
            }
        }
        cout<<ans<<"\n";
