using namespace std;

struct Interval {
    int l, r;
    long long w;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    while (cin >> n && n) {
        vector<Interval> a(n);
        vector<int> coords;
        coords.reserve(2 * n);

        for (int i = 0; i < n; ++i) {
            cin >> a[i].l >> a[i].r >> a[i].w;
            coords.push_back(a[i].l);
            coords.push_back(a[i].r);
        }

        sort(coords.begin(), coords.end());
        coords.erase(unique(coords.begin(), coords.end()), coords.end());

        int m = (int)coords.size();

        vector<vector<pair<int, long long>>> startAt(m);
        for (int i = 0; i < n; ++i) {
            int L = lower_bound(coords.begin(), coords.end(), a[i].l) - coords.begin();
            int R = lower_bound(coords.begin(), coords.end(), a[i].r) - coords.begin();
            startAt[L].push_back({R, a[i].w});
        }

        const long long NEG = -(1LL << 60);

        // dp[i][j]: maximum income when the two rooms become free at
        // compressed times i and j (i <= j), and we are processing from time max(i,j).
        vector<vector<long long>> dp(m + 1, vector<long long>(m + 1, NEG));

        // Base: after the last time point, no more income.
        dp[m][m] = 0;
        for (int i = 0; i <= m; ++i) {
            dp[m][i] = dp[i][m] = 0;
        }

        for (int i = m - 1; i >= 0; --i) {
            for (int j = m - 1; j >= i; --j) {
                int t = j; // current time is the later free time (since i <= j)

                long long best = 0;
                if (t + 1 <= m) best = dp[min(i, t + 1)][max(i, t + 1)]; // skip this time

                // If room corresponding to j is free now, we may start an interval at time t in it.
                for (auto &[R, W] : startAt[t]) {
                    int ni = i, nj = R;
                    if (ni > nj) swap(ni, nj);
                    best = max(best, W + dp[ni][nj]);
                }

                // If both rooms are free now (i == j), we can also place one interval in the "other" room;
                // state transition is actually the same, but only one interval can start in one room at a time.
                // Starting two intervals simultaneously is handled through subsequent states.

                dp[i][j] = best;
            }
        }

        cout << dp[0][0] << '\n';
    }

    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null) {
            int n = Integer.parseInt(line.trim());
            if (n == 0) break;

            int[] start = new int[n];
            int[] end = new int[n];
            int[] price = new int[n];
            int maxDay = 0;

            for (int i = 0; i < n; i++) {
                String[] parts = br.readLine().split(" ");
                start[i] = Integer.parseInt(parts[0]);
                end[i] = Integer.parseInt(parts[1]);
                price[i] = Integer.parseInt(parts[2]);
                if (end[i] > maxDay) maxDay = end[i];
            }

            // dp1[t] = max profit with one room up to day t
            // dp2[t] = max profit with two rooms up to day t
            int[] dp1 = new int[maxDay + 2];
            int[] dp2 = new int[maxDay + 2];

            // Group applications by end day
            List<int[]>[] byEnd = new ArrayList[maxDay + 2];
            for (int d = 0; d <= maxDay + 1; d++) {
                byEnd[d] = new ArrayList<>();
            }
            for (int i = 0; i < n; i++) {
                byEnd[end[i]].add(new int[]{start[i], price[i]});
            }

            for (int t = 1; t <= maxDay; t++) {
                // Carry forward previous values
                dp1[t] = dp1[t-1];
                dp2[t] = dp2[t-1];

                for (int[] app : byEnd[t]) {
                    int s = app[0];
                    int w = app[1];
                    // Use one room: take this application + best with one room before start
                    dp1[t] = Math.max(dp1[t], dp1[s-1] + w);
                    // Use two rooms: 
                    // Case 1: take this application + best with one room before start
                    dp2[t] = Math.max(dp2[t], dp1[s-1] + w);
                    // Case 2: take this application + another application ending at same day in second room
                    // already handled by iterating all pairs? Actually we need to consider two applications ending at t
                    // We'll handle two applications separately below
                }

                // Handle two applications ending at the same day t
                List<int[]> appsToday = byEnd[t];
                int m = appsToday.size();
                for (int i = 0; i < m; i++) {
                    for (int j = i+1; j < m; j++) {
                        int s1 = appsToday.get(i)[0], w1 = appsToday.get(i)[1];
                        int s2 = appsToday.get(j)[0], w2 = appsToday.get(j)[1];
                        // Both rooms used, need max profit before min(start1, start2)
                        int minStart = Math.min(s1, s2);
                        dp2[t] = Math.max(dp2[t], dp2[minStart-1] + w1 + w2);
                    }
                }

                // Also consider taking one application today and another earlier
                for (int[] app : appsToday) {
                    int s = app[0], w = app[1];
                    // This application + best with two rooms before start
                    dp2[t] = Math.max(dp2[t], dp2[s-1] + w);
                }
            }

            System.out.println(dp2[maxDay]);
        }
    }
}

