import java.io.*;
import java.util.*;

/*
Weighted interval scheduling on 2 identical rooms.

Model:
Each application is an interval [l, r] with profit w.
At any time, at most 2 accepted intervals may overlap.

Classic DP:
Sort intervals by ending time.
Let dp[i][j] be the maximum profit where the last accepted interval in room 1 is i
and in room 2 is j (0 means empty), with intervals considered in nondecreasing end time.
A state is valid if interval i and j can coexist as the current last intervals.

Transition:
From state (a, b), try to add next interval k (> max(a,b) in processing order):
- if interval k starts after interval a ends, it can go to room 1 -> state (k, b)
- if interval k starts after interval b ends, it can go to room 2 -> state (a, k)

To make this efficient, process intervals by end time and use DP over ordered pairs.
A better formulation:
Let f[i][j] for i < j be max profit when i and j are the last intervals in the two rooms,
and all chosen intervals are among first j intervals, with j being the most recently processed.
Transition by adding j after some k < j:
f[i][j] = max(
    max over k < j and end[k] < start[j] of f[i][k] + w[j],
    if end[i] < start[j] then best1[i][p(j)] + w[j]
)
This gets messy.

Instead, use min-cost max-flow on interval graph? Too heavy.

Observation: 2-room weighted interval scheduling equals maximum weight subset with overlap capacity 2.
This can be solved by min-cost max-flow on a DAG of time points:
- Compress all distinct interval endpoints.
- Add edge t -> t+1 with capacity 2, cost 0.
- For each request [l, r], add edge idx(l) -> idx(r) with capacity 1, cost = profit.
Then compute maximum cost flow from source(first time) to sink(last time) with 2 units.
Because moving along timeline represents room availability, selecting an interval consumes one room over its duration.
This is standard and efficient enough.

We need maximum cost with exactly 2 units sent, but sending fewer is allowed effectively by zero-cost timeline edges.
So send 2 units; unused capacity just follows timeline edges.

Input format:
Multiple datasets. Each starts with n.
Likely terminated by 0.
Then n lines: i j w

Assume inclusive periods [i, j]. For overlap on same room, intervals [a,b] and [c,d] are compatible if c > b.
In timeline network, use end as j+1 to model inclusiveness.
So each request occupies [i, j+1) in compressed coordinates.

Use long for profits.

Max-cost flow on DAG with SPFA is okay for moderate n, but better use successive longest path in DAG order since graph is acyclic.
However reverse edges break acyclicity during residual processing.
Given only 2 units of flow, SPFA twice is fine.

*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Long.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int to, rev, cap;
        long cost;
        Edge(int to, int rev, int cap, long cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    static class MaxCostFlow {
        int n;
        ArrayList<Edge>[] g;

        @SuppressWarnings("unchecked")
        MaxCostFlow(int n) {
            this.n = n;
            g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        }

        void addEdge(int s, int t, int cap, long cost) {
            Edge a = new Edge(t, g[t].size(), cap, cost);
            Edge b = new Edge(s, g[s].size(), 0, -cost);
            g[s].add(a);
            g[t].add(b);
        }

        long maxCostFlow(int s, int t, int maxf) {
            long res = 0;
            int flow = 0;

            long[] dist = new long[n];
            boolean[] inq = new boolean[n];
            int[] pv = new int[n];
            int[] pe = new int[n];

            while (flow < maxf) {
                Arrays.fill(dist, Long.MIN_VALUE / 4);
                dist[s] = 0;

                ArrayDeque<Integer> q = new ArrayDeque<>();
                q.add(s);
                inq[s] = true;

                while (!q.isEmpty()) {
                    int v = q.poll();
                    inq[v] = false;
                    for (int i = 0; i < g[v].size(); i++) {
                        Edge e = g[v].get(i);
                        if (e.cap > 0 && dist[v] + e.cost > dist[e.to]) {
                            dist[e.to] = dist[v] + e.cost;
                            pv[e.to] = v;
                            pe[e.to] = i;
                            if (!inq[e.to]) {
                                inq[e.to] = true;
                                q.add(e.to);
                            }
                        }
                    }
                }

                if (dist[t] == Long.MIN_VALUE / 4) break;

                int addf = maxf - flow;
                for (int v = t; v != s; v = pv[v]) {
                    Edge e = g[pv[v]].get(pe[v]);
                    addf = Math.min(addf, e.cap);
                }

                for (int v = t; v != s; v = pv[v]) {
                    Edge e = g[pv[v]].get(pe[v]);
                    e.cap -= addf;
                    g[v].get(e.rev).cap += addf;
                }

                flow += addf;
                res += dist[t] * addf;
            }

            return res;
        }
    }

    static class Request {
        long l, r, w;
        Request(long l, long r, long w) {
            this.l = l;
            this.r = r;
            this.w = w;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            long nl = fs.nextLong();
            if (nl == Long.MIN_VALUE) break;
            int n = (int) nl;
            if (n == 0) break;

            Request[] req = new Request[n];
            ArrayList<Long> coords = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                long l = fs.nextLong();
                long r = fs.nextLong();
                long w = fs.nextLong();
                // inclusive [l, r] -> half-open [l, r+1)
                req[i] = new Request(l, r + 1, w);
                coords.add(l);
                coords.add(r + 1);
            }

            Collections.sort(coords);
            ArrayList<Long> uniq = new ArrayList<>();
            for (long x : coords) {
                if (uniq.isEmpty() || uniq.get(uniq.size() - 1) != x) uniq.add(x);
            }

            int m = uniq.size();
            MaxCostFlow mcf = new MaxCostFlow(m);

            for (int i = 0; i < m - 1; i++) {
                mcf.addEdge(i, i + 1, 2, 0);
            }

            for (Request rq : req) {
                int u = lowerBound(uniq, rq.l);
                int v = lowerBound(uniq, rq.r);
                mcf.addEdge(u, v, 1, rq.w);
            }

            long ans = mcf.maxCostFlow(0, m - 1, 2);
            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }

    static int lowerBound(ArrayList<Long> a, long x) {
        int l = 0, r = a.size();
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (a.get(mid) < x) l = mid + 1;
            else r = mid;
        }
        return l;
    }
}

import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    it = iter(data)
    out = []

    while True:
        try:
            n = int(next(it))
        except StopIteration:
            break

        if n == 0:
            break

        req = []
        coords = set()

        for _ in range(n):
            a = int(next(it))
            b = int(next(it))
            w = int(next(it))
            req.append((a, b, w))
            coords.add(a)
            coords.add(b)

        # Coordinate compression on interval endpoints.
        xs = sorted(coords)
        idx = {x: i for i, x in enumerate(xs)}
        m = len(xs)

        # Bucket requests by ending coordinate.
        end_at = [[] for _ in range(m)]
        for a, b, w in req:
            ia = idx[a]
            ib = idx[b]
            end_at[ib].append((ia, w))

        NEG = -10**18

        # dp[i][j]: best profit where room1 is free from xs[i], room2 from xs[j]
        # after processing all requests ending up to current endpoint.
        dp = [[NEG] * m for _ in range(m)]
        dp[0][0] = 0

        for e in range(m):
            ndp = [row[:] for row in dp]

            # Advance free times that are <= current endpoint to current endpoint.
            for i in range(e + 1):
                for j in range(e + 1):
                    val = dp[i][j]
                    if val == NEG:
                        continue
                    if i < e:
                        if val > ndp[e][j]:
                            ndp[e][j] = val
                    if j < e:
                        if val > ndp[i][e]:
                            ndp[i][e] = val

            dp = ndp

            # Process all requests ending at e
            for s, w in end_at[e]:
                ndp = [row[:] for row in dp]
                for i in range(m):
                    for j in range(m):
                        cur = dp[i][j]
                        if cur == NEG:
                            continue
                        # Put this concert in room 1 if room 1 is free by start time
                        if i <= s:
                            nv = cur + w
                            if nv > ndp[e][j]:
                                ndp[e][j] = nv
                        # Put this concert in room 2 if room 2 is free by start time
                        if j <= s:
                            nv = cur + w
                            if nv > ndp[i][e]:
                                ndp[i][e] = nv
                dp = ndp

        ans = 0
        for i in range(m):
            for j in range(m):
                if dp[i][j] > ans:
                    ans = dp[i][j]

        out.append(str(ans))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
